<?php
namespace Tests\Feature;
use App\Settings\Settings;use App\Reliability\Recovery;use App\Domain\{Access,AudioStore,Failure};use App\Jobs\{PurgeLesson,ApplyRetention};
use Illuminate\Foundation\Testing\DatabaseTransactions;use Illuminate\Support\Facades\{DB,Hash,Queue};use Illuminate\Support\Str;use Tests\TestCase;
final class SettingsRecoveryTest extends TestCase {
 use DatabaseTransactions;
 protected function setUp():void {parent::setUp();DB::table('settings_versions')->where('active',true)->update(['active'=>false]);config(['classroom.qwen'=>['model'=>'qwen3.8-livetranslate-flash-realtime','region'=>'cn-beijing','workspace_id'=>'fixture','endpoint'=>'ws://127.0.0.1:18082/api-ws/v1/realtime','api_key'=>'fixture-secret-model','allow_test_endpoint'=>true],'classroom.oss'=>['endpoint'=>'https://s3.oss-cn-hangzhou.aliyuncs.com','region'=>'cn-hangzhou','bucket'=>'fixture-bucket','key'=>'fixture-key','secret'=>'fixture-oss-secret','prefix'=>'explicit-fixture','presign_seconds'=>120]]);}
 private function actor(string $role='admin'):object {$id=DB::table('users')->insertGetId(['student_id'=>'000'.Str::uuid(),'name'=>'Тест Ї Є','password'=>Hash::make('valid-password-2026'),'role'=>$role,'must_change_password'=>false]);return Access::user($id);}
 private function lesson(object $actor,string $status='ended'):int {$c=DB::table('courses')->insertGetId(['name'=>'Synthetic recovery course']);return DB::table('lessons')->insertGetId(['course_id'=>$c,'creator_id'=>$actor->id,'recorder_user_id'=>$actor->id,'name'=>'Synthetic Щ Ї classroom','status'=>$status,'target_language'=>'zh','idempotency_key'=>(string)Str::uuid(),'ended_at'=>$status==='ended'?now():null]);}
 private function failCode(string $code,callable $fn):void {try{$fn();$this->fail('Expected '.$code);}catch(Failure $e){$this->assertSame($code,$e->errorCode);}}
 private function auth(object $actor):static {return $this->withSession(['uid'=>$actor->id,'reauth_until'=>time()+900,'reauth_at'=>time()]);}
 public function test_settings_are_admin_only_and_secret_fields_are_masked():void {$this->getJson('/api/admin/settings')->assertStatus(401);$u=$this->actor('user');$this->auth($u)->getJson('/api/admin/settings')->assertStatus(403);$a=$this->actor();$r=$this->auth($a)->getJson('/api/admin/settings')->assertOk();$r->assertJsonMissingPath('model.api_key')->assertJsonMissingPath('oss.secret')->assertJsonMissingPath('oss.key');$this->getJson('/api/public-settings')->assertOk()->assertJsonMissingPath('prices')->assertJsonMissingPath('model');}
 public function test_versions_encrypt_secrets_blank_preserves_and_conflicts_reject():void {$a=$this->actor();$v=Settings::version('model');$result=Settings::save('model',['api_key'=>'unique-fixture-private-secret'],$v,$a);$id=$result['versions']['model'];$encrypted=DB::table('settings_versions')->where('id',$id)->value('payload_encrypted');$this->assertStringNotContainsString('unique-fixture-private-secret',$encrypted);$this->assertSame('unique-fixture-private-secret',Settings::values('model')['api_key']);Settings::save('model',['api_key'=>''],$id,$a);$this->assertSame('unique-fixture-private-secret',Settings::values('model')['api_key']);$this->failCode('settings_version_conflict',fn()=>Settings::save('model',[],$id,$a));}
 public function test_model_and_oss_endpoints_reject_ssrf_before_network():void {$a=$this->actor();$this->failCode('settings_values_invalid',fn()=>Settings::save('model',['endpoint'=>'http://169.254.169.254/latest/meta-data/'],Settings::version('model'),$a));$this->failCode('settings_values_invalid',fn()=>Settings::save('oss',['endpoint'=>'https://127.0.0.1/'],Settings::version('oss'),$a));$this->failCode('settings_values_invalid',fn()=>Settings::save('model',['api_key'=>['bad']],Settings::version('model'),$a));}
 public function test_frozen_model_settings_survive_new_active_version():void {$a=$this->actor();$id=$this->lesson($a,'ready');$first=DB::transaction(fn()=>Settings::freezeModel($id));Settings::save('model',['api_key'=>'new-fixture-secret-key'],Settings::version('model'),$a);$again=DB::transaction(fn()=>Settings::freezeModel($id));$this->assertSame($first,$again);$next=$this->lesson($a,'ready');$this->assertSame('new-fixture-secret-key',DB::transaction(fn()=>Settings::freezeModel($next))['api_key']);$public=Access::publicLesson(Access::lesson($id,$a));$this->assertArrayNotHasKey('model_settings_version',$public);$this->assertArrayNotHasKey('storage_version',$public);}
 public function test_sensitive_save_requires_recent_auth_and_tests_are_async():void {Queue::fake();$a=$this->actor();$this->withSession(['uid'=>$a->id])->putJson('/api/admin/settings/policies',['values'=>Settings::defaults(),'expected_version'=>Settings::version('policies'),'confirmed'=>true])->assertStatus(403);$r=$this->auth($a)->postJson('/api/admin/settings/model/test',['confirmed'=>true])->assertOk()->assertJsonPath('test.status','queued');Queue::assertPushed(\App\Jobs\TestConnection::class,1);$this->auth($a)->getJson('/api/admin/connection-tests/'.$r->json('test.id'))->assertOk()->assertJsonMissingPath('test.settings_version');$other=$this->actor();$this->auth($other)->getJson('/api/admin/connection-tests/'.$r->json('test.id'))->assertStatus(404);}
 public function test_invalid_retention_and_price_values_are_explained():void {$a=$this->actor();$p=Settings::defaults();$p['auto_purge']=true;$this->failCode('settings_values_invalid',fn()=>Settings::save('policies',$p,Settings::version('policies'),$a));$p=Settings::defaults();$p['prices']=[['region'=>'cn-beijing','currency'=>'CNY','item'=>'audio_input','unit_price'=>'fake','effective_at'=>'2026-10-09T00:00:00Z']];$this->failCode('usage_price_invalid',fn()=>Settings::save('policies',$p,Settings::version('policies'),$a));}
 public function test_restart_pauses_and_marks_unfinished_units_without_rewriting_completed():void {Queue::fake();$a=$this->actor('user');$id=$this->lesson($a,'live');$sid=(string)Str::uuid();DB::table('lessons')->where('id',$id)->update(['translation_status'=>'ready','media_samples'=>1600,'recorder_epoch'=>1]);DB::table('model_sessions')->insert(['id'=>$sid,'lesson_id'=>$id,'recorder_user_id'=>$a->id,'base_sample'=>0,'model'=>'fixture','config'=>'{"epoch":1}','status'=>'ready']);foreach(['streaming','completed']as$status)DB::table('subtitle_units')->insert(['lesson_id'=>$id,'model_session_id'=>$sid,'provider_unit_id'=>$status,'kind'=>'source','status'=>$status,'original_text'=>'Synthetic text']);Recovery::restart();$this->assertDatabaseHas('lessons',['id'=>$id,'status'=>'paused','translation_status'=>'interrupted','recorder_connection'=>null]);$this->assertDatabaseHas('subtitle_units',['lesson_id'=>$id,'provider_unit_id'=>'streaming','status'=>'interrupted']);$this->assertDatabaseHas('subtitle_units',['lesson_id'=>$id,'provider_unit_id'=>'completed','status'=>'completed','original_text'=>'Synthetic text']);$this->assertDatabaseHas('recording_issues',['lesson_id'=>$id,'kind'=>'translation_uncertain','start_sample'=>0,'end_sample'=>1600]);}
 public function test_capture_issue_requires_epoch_participation_and_preserves_unknown_gap():void {$u=$this->actor('user');$other=$this->actor('user');$id=$this->lesson($u,'paused');DB::table('lessons')->where('id',$id)->update(['recorder_epoch'=>2,'recorder_user_id'=>$other->id]);$sid=(string)Str::uuid();DB::table('model_sessions')->insert(['id'=>$sid,'lesson_id'=>$id,'recorder_user_id'=>$u->id,'base_sample'=>0,'model'=>'fixture','config'=>'{"epoch":1}','status'=>'finished']);$v=['epoch'=>1,'reason'=>'network_disconnected','last_ack_sequence'=>-1,'next_sequence'=>3,'estimated_lost_ms'=>500];$r=Recovery::clientIssue($id,$u,$v);$this->assertNull($r['issue']['end_sample']);$this->assertSame('skip_unreceived',$r['issue']['details']['media_strategy']);$this->assertSame($r['issue']['id'],Recovery::clientIssue($id,$u,$v)['issue']['id']);$this->failCode('recorder_stale',fn()=>Recovery::clientIssue($id,$other,$v));}
 public function test_replay_is_ordered_bounded_and_does_not_expose_internal_controls():void {$u=$this->actor();$id=$this->lesson($u);$start=Access::event($id,'lesson.updated',['lesson'=>['id'=>$id]]);Access::event($id,'control.end',['actor_id'=>$u->id]);$last=Access::event($id,'subtitle.updated',['unit'=>['id'=>1,'text'=>'Synthetic']]);$r=Recovery::replay($id,$start,$last);$this->assertSame('replay',$r['mode']);$this->assertCount(1,$r['missed_events']);$this->assertSame('subtitle.updated',$r['missed_events'][0]['event_type']);for($n=0;$n<501;$n++)DB::table('lesson_events')->insert(['lesson_id'=>$id,'event_type'=>'lesson.updated','payload'=>'{}']);$r=Recovery::replay($id,$start,(int)DB::table('lesson_events')->max('seq'));$this->assertTrue($r['truncated']);$this->assertSame('snapshot',$r['mode']);$this->assertEmpty($r['missed_events']);}
 public function test_purge_requires_soft_delete_exact_name_and_recent_admin():void {Queue::fake();$a=$this->actor();$id=$this->lesson($a);$body=['confirmed'=>true,'confirm_name'=>'Synthetic Щ Ї classroom'];$this->auth($a)->postJson('/api/admin/lessons/'.$id.'/purge',$body)->assertStatus(409);DB::table('lessons')->where('id',$id)->update(['deleted_at'=>now()]);$this->auth($a)->postJson('/api/admin/lessons/'.$id.'/purge',[...$body,'confirm_name'=>'wrong'])->assertStatus(422);$this->auth($a)->postJson('/api/admin/lessons/'.$id.'/purge',$body)->assertOk()->assertJsonPath('status','queued');Queue::assertPushed(PurgeLesson::class,1);$this->auth($a)->postJson('/api/admin/lessons/'.$id.'/purge',$body)->assertOk();Queue::assertPushed(PurgeLesson::class,1);}
 public function test_empty_fixture_purge_is_idempotent_and_audit_is_preserved():void {Queue::fake();$a=$this->actor();$id=$this->lesson($a);DB::table('lessons')->where('id',$id)->update(['deleted_at'=>now(),'purge_status'=>'queued']);DB::table('audit')->insert(['lesson_id'=>$id,'user_id'=>$a->id,'action'=>'fixture.audit']);(new PurgeLesson($id))->handle();(new PurgeLesson($id))->handle();$this->assertDatabaseHas('lessons',['id'=>$id,'purge_status'=>'purged']);$this->assertDatabaseHas('audit',['lesson_id'=>$id,'action'=>'fixture.audit']);$this->auth($a)->postJson('/api/admin/lessons/'.$id.'/restore',['confirmed'=>true])->assertStatus(404);}
 public function test_retention_defaults_keep_data_and_opt_in_queues_old_ended_only():void {Queue::fake();$a=$this->actor();$id=$this->lesson($a);DB::table('lessons')->where('id',$id)->update(['ended_at'=>now()->subDays(10)]);(new ApplyRetention)->handle();$this->assertDatabaseHas('lessons',['id'=>$id,'purge_status'=>null]);$p=Settings::defaults();$p['auto_purge']=true;$p['retention_days']=5;Settings::save('policies',$p,Settings::version('policies'),$a);(new ApplyRetention)->handle();$this->assertDatabaseHas('lessons',['id'=>$id,'purge_status'=>'queued']);Queue::assertPushed(PurgeLesson::class);$this->assertDatabaseHas('lesson_events',['lesson_id'=>$id,'event_type'=>'lesson.updated']);}
 public function test_purge_removes_private_export_and_copied_glossary_and_cannot_rebuild():void {
  Queue::fake();$a=$this->actor();$id=$this->lesson($a);$course=DB::table('lessons')->where('id',$id)->value('course_id');
  \App\Glossary\Glossary::snapshot($id,$course,'zh');$sid=(string)Str::uuid();DB::table('model_sessions')->insert(['id'=>$sid,'lesson_id'=>$id,'base_sample'=>0,'model'=>'explicit-fixture','status'=>'finished','config'=>'{}']);DB::table('subtitle_units')->insert(['lesson_id'=>$id,'model_session_id'=>$sid,'provider_unit_id'=>'purge-fixture','kind'=>'source','original_text'=>'Synthetic private export content Ї','status'=>'completed']);
  $service=new \App\Exports\ExportService;$task=$service->create($id,$a,['format'=>'txt','layout'=>'source','text_version'=>'original','idempotency_key'=>(string)Str::uuid()]);$service->build($task['id'],new \App\Exports\SubtitleFormatter);$path=$service->file($task['id'],$a)['path'];$this->assertFileExists($path);file_put_contents($path.'.tmp','Synthetic incomplete temporary export');
  $locks=(new \App\Jobs\BuildSubtitleExport($task['id']))->middleware();$this->assertCount(2,$locks);$this->assertSame('lesson-data:'.$id,$locks[1]->key);$this->assertTrue($locks[1]->shareKey);
  DB::table('lessons')->where('id',$id)->update(['deleted_at'=>now(),'purge_status'=>'queued']);(new PurgeLesson($id))->handle();$this->assertFileDoesNotExist($path);$this->assertFileDoesNotExist($path.'.tmp');$this->assertDatabaseMissing('lesson_glossary_snapshots',['lesson_id'=>$id]);$this->assertDatabaseMissing('subtitle_export_rows',['export_id'=>$task['id']]);$this->assertDatabaseHas('subtitle_exports',['id'=>$task['id'],'status'=>'expired','file_path'=>null,'metadata'=>'{}','report'=>'{}']);$service->build($task['id'],new \App\Exports\SubtitleFormatter);$this->assertFileDoesNotExist($path);
 }
 public function test_multilingual_course_search_time_lookup_and_download_gates():void {$u=$this->actor('user');$id=$this->lesson($u);$sid=(string)Str::uuid();DB::table('model_sessions')->insert(['id'=>$sid,'lesson_id'=>$id,'base_sample'=>0,'model'=>'fixture','config'=>'{}','status'=>'finished']);$unit=DB::table('subtitle_units')->insertGetId(['lesson_id'=>$id,'model_session_id'=>$sid,'provider_unit_id'=>'fixture','kind'=>'source','original_text'=>'English 中文 ЇЄҐ 100%_','status'=>'completed','start_sample'=>0,'end_sample'=>16000,'timing_precision'=>'server_segment']);$course=DB::table('lessons')->where('id',$id)->value('course_id');$this->getJson('/api/courses/'.$course.'/subtitles?q='.rawurlencode('ЇЄҐ'))->assertOk()->assertJsonPath('units.0.id',$unit);$this->getJson('/api/lessons/'.$id.'/subtitles?at_sample=1000')->assertOk()->assertJsonPath('units.0.id',$unit);$this->getJson('/api/lessons/'.$id.'/subtitles?at_sample=20000')->assertOk()->assertJsonCount(0,'units');$this->get('/api/lessons/'.$id.'/download')->assertStatus(401);$this->auth($u)->getJson('/api/lessons/'.$id.'/download')->assertStatus(403)->assertJsonPath('code','recording_download_disabled');}
 public function test_stale_capture_issue_service_rejects_deleted_purged_or_disabled_course():void {
  $u=$this->actor('user');$id=$this->lesson($u,'paused');DB::table('lessons')->where('id',$id)->update(['recorder_epoch'=>1]);$v=['epoch'=>1,'reason'=>'network_disconnected','last_ack_sequence'=>-1,'next_sequence'=>0];$course=DB::table('lessons')->where('id',$id)->value('course_id');
  DB::table('courses')->where('id',$course)->update(['enabled'=>false]);$this->failCode('lesson_unavailable',fn()=>Recovery::clientIssue($id,$u,$v));DB::table('courses')->where('id',$course)->update(['enabled'=>true]);
  DB::table('lessons')->where('id',$id)->update(['deleted_at'=>now()]);$this->failCode('lesson_unavailable',fn()=>Recovery::clientIssue($id,$u,$v));DB::table('lessons')->where('id',$id)->update(['deleted_at'=>null,'purge_status'=>'purged']);$this->failCode('lesson_unavailable',fn()=>Recovery::clientIssue($id,$u,$v));
  $this->assertDatabaseMissing('recording_issues',['lesson_id'=>$id]);$this->assertDatabaseMissing('lesson_events',['lesson_id'=>$id]);
 }
}
